// Pure rules of the public order: input validation and pricing. No I/O.
import { ApiError } from './http.ts';
import type { PublicServiceRow } from './public-order-store.ts';

/** Request body contract shared with apps/web (public-order-client.ts). */
export type PublicOrderStartPayload = {
  /** Random id generated by the browser: makes the call idempotent. */
  clientKey: string;
  customer: { name: string; phone: string; email?: string; notes?: string };
  whatsappOptIn: boolean;
  items: { serviceId: string; quantity: number; variantId?: string }[];
  /** What the customer saw. Never trusted: it only detects stale price lists. */
  expectedTotalCents?: number;
  /** Honeypot: real users never fill it. */
  website?: string;
};
export type PublicOrderTokenPayload = { token: string };
export type PublicOrderSubmitPayload = PublicOrderTokenPayload & {
  /**
   * How many photos the browser sent to each destination (the opaque ids returned by start).
   * The server compares them with what is really stored: a size that lost photos is never
   * confirmed as complete.
   */
  expectedFiles?: Record<string, number>;
  /** The customer saw the failed photos and chose to send the order without them. */
  acceptPartial?: boolean;
  /**
   * The uploads that make up the order, in the order the customer sees them. Anything else the
   * server holds for the draft (a photo removed or moved to another size after it was sent) is
   * retired, and the position here is the order of the final file numbers. It never names a file.
   */
  uploadIds?: string[];
};

export const LIMITS = {
  maxServices: 10,
  maxQuantityPerService: 1000,
  nameMin: 2,
  nameMax: 80,
  emailMax: 120,
  notesMax: 500,
} as const;

/** What one order may hold. Professionals send whole Lightroom exports, so theirs are larger. */
export type OrderLimits = {
  maxServices: number;
  maxQuantityPerService: number;
  /** Uploads listed in one confirmation. */
  maxUploads: number;
  /** Photos announced for one destination in `expectedFiles`. */
  maxFilesPerDestination: number;
};
export const PUBLIC_ORDER_LIMITS: OrderLimits = {
  maxServices: LIMITS.maxServices,
  maxQuantityPerService: LIMITS.maxQuantityPerService,
  maxUploads: 500,
  maxFilesPerDestination: 1000,
};
export const PROFESSIONAL_ORDER_LIMITS: OrderLimits = {
  maxServices: 30,
  maxQuantityPerService: 50_000,
  maxUploads: 1000,
  maxFilesPerDestination: 1000,
};

/** Request body of professional-order-start: who is ordering comes from the verified JWT. */
export type ProfessionalOrderStartPayload = {
  clientKey: string;
  /** WhatsApp number for the "ready" notice; the portal pre-fills the customer's own. */
  phone: string;
  notes?: string;
  items: { serviceId: string; quantity: number; variantId: string }[];
  expectedTotalCents?: number;
};

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const CLIENT_KEY = /^[A-Za-z0-9_-]{16,64}$/;
// Same shape the customers table accepts.
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// eslint-disable-next-line no-control-regex -- reject ASCII control characters in free text.
const CONTROL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/;

const invalid = (message: string, code = 'invalid_request') =>
  new ApiError(message, 400, code);

export type ParsedStart = {
  clientKey: string;
  name: string;
  phone: string;
  email: string | null;
  notes: string | null;
  whatsappOptIn: boolean;
  items: { serviceId: string; quantity: number; variantId?: string }[];
  expectedTotalCents: number | null;
};

function cleanText(
  value: unknown,
  label: string,
  max: number,
  options: { required: boolean; min?: number },
) {
  if (value === undefined || value === null || value === '') {
    if (options.required) throw invalid(`Completá ${label}.`);
    return null;
  }
  if (typeof value !== 'string' || CONTROL.test(value))
    throw invalid(`${label} no es válido.`);
  const text = value.replace(/\s+/g, ' ').trim();
  if (!text) {
    if (options.required) throw invalid(`Completá ${label}.`);
    return null;
  }
  if (text.length > max || text.length < (options.min ?? 1))
    throw invalid(`${label} no es válido.`);
  return text;
}

export function parseStartPayload(
  input: Partial<PublicOrderStartPayload>,
): ParsedStart {
  if (typeof input.website === 'string' && input.website.trim())
    throw invalid('La solicitud no es válida.');
  if (typeof input.clientKey !== 'string' || !CLIENT_KEY.test(input.clientKey))
    throw invalid('La solicitud no es válida.');
  const customer = input.customer;
  if (typeof customer !== 'object' || customer === null)
    throw invalid('Completá tus datos.');
  const name = cleanText(customer.name, 'Tu nombre', LIMITS.nameMax, {
    required: true,
    min: LIMITS.nameMin,
  })!;
  if (typeof customer.phone !== 'string')
    throw invalid('Completá tu número de WhatsApp.', 'invalid_phone');
  const email = cleanText(customer.email, 'El email', LIMITS.emailMax, {
    required: false,
  });
  if (email && !EMAIL.test(email)) throw invalid('El email no es válido.');
  const notes = cleanText(customer.notes, 'La nota', LIMITS.notesMax, {
    required: false,
  });
  if (typeof input.whatsappOptIn !== 'boolean')
    throw invalid('La solicitud no es válida.');
  const items = parseItems(input.items, PUBLIC_ORDER_LIMITS, false);
  if (
    input.expectedTotalCents !== undefined &&
    (!Number.isSafeInteger(input.expectedTotalCents) ||
      input.expectedTotalCents < 0)
  )
    throw invalid('La solicitud no es válida.');
  return {
    clientKey: input.clientKey,
    name,
    phone: customer.phone,
    email,
    notes,
    whatsappOptIn: input.whatsappOptIn,
    items,
    expectedTotalCents: input.expectedTotalCents ?? null,
  };
}

function parseItems(
  raw: unknown,
  limits: OrderLimits,
  requireVariant: boolean,
): { serviceId: string; quantity: number; variantId?: string }[] {
  if (
    !Array.isArray(raw) ||
    raw.length === 0 ||
    raw.length > limits.maxServices
  )
    throw invalid('Elegí al menos un tamaño.', 'invalid_items');
  const seen = new Set<string>();
  return raw.map((item) => {
    if (
      typeof item !== 'object' ||
      item === null ||
      typeof item.serviceId !== 'string' ||
      !UUID.test(item.serviceId) ||
      !Number.isInteger(item.quantity) ||
      item.quantity < 1 ||
      item.quantity > limits.maxQuantityPerService
    )
      throw invalid('Revisá las cantidades.', 'invalid_items');
    if (
      (requireVariant || item.variantId !== undefined) &&
      (typeof item.variantId !== 'string' || !UUID.test(item.variantId))
    )
      throw invalid('Revisá el tipo de papel.', 'invalid_items');
    const id = item.serviceId.toLowerCase();
    if (seen.has(id)) throw invalid('Revisá las cantidades.', 'invalid_items');
    seen.add(id);
    return {
      serviceId: id,
      quantity: item.quantity as number,
      variantId: (item.variantId as string | undefined)?.toLowerCase(),
    };
  });
}

export type ParsedProfessionalStart = {
  clientKey: string;
  phone: string;
  notes: string | null;
  items: { serviceId: string; quantity: number; variantId: string }[];
  expectedTotalCents: number | null;
};

export function parseProfessionalStartPayload(
  input: Partial<ProfessionalOrderStartPayload>,
): ParsedProfessionalStart {
  if (typeof input.clientKey !== 'string' || !CLIENT_KEY.test(input.clientKey))
    throw invalid('La solicitud no es válida.');
  if (typeof input.phone !== 'string')
    throw invalid('Completá tu número de WhatsApp.', 'invalid_phone');
  const notes = cleanText(input.notes, 'La nota', LIMITS.notesMax, {
    required: false,
  });
  const items = parseItems(input.items, PROFESSIONAL_ORDER_LIMITS, true) as {
    serviceId: string;
    quantity: number;
    variantId: string;
  }[];
  if (
    input.expectedTotalCents !== undefined &&
    (!Number.isSafeInteger(input.expectedTotalCents) ||
      input.expectedTotalCents < 0)
  )
    throw invalid('La solicitud no es válida.');
  return {
    clientKey: input.clientKey,
    phone: input.phone,
    notes,
    items,
    expectedTotalCents: input.expectedTotalCents ?? null,
  };
}

export type PricedLine = {
  serviceId: string;
  name: string;
  quantity: number;
  unitPriceCents: number;
  totalCents: number;
  variantId?: string;
  photoServiceId?: string;
};

/**
 * The only place a price is computed. It reads the catalog row (never the request): the
 * order total is `sum(quantity × catalog price)`. A service that is not in the catalog
 * (inactive, not public, not orderable, other Business) is rejected, not silently dropped.
 */
export function priceOrder(
  catalog: PublicServiceRow[],
  items: { serviceId: string; quantity: number; variantId?: string }[],
) {
  const byId = new Map(catalog.map((service) => [service.id, service]));
  const lines: PricedLine[] = [];
  for (const item of items) {
    const service = byId.get(item.serviceId);
    if (!service)
      throw new ApiError(
        'Uno de los tamaños ya no está disponible. Actualizá la página.',
        409,
        'service_unavailable',
      );
    if (item.variantId && service.variant_id !== item.variantId)
      throw new ApiError(
        'El papel ya no está disponible.',
        409,
        'service_unavailable',
      );
    const tier = service.tiers?.find(
      (x) =>
        x.min_quantity <= item.quantity &&
        (x.max_quantity === null || x.max_quantity >= item.quantity),
    );
    if (service.tiers && !tier)
      throw new ApiError(
        'No hay precio disponible para esa cantidad de copias.',
        409,
        'service_unavailable',
      );
    const unitPriceCents = tier?.unit_price_cents ?? service.unit_price_cents;
    const totalCents = item.quantity * unitPriceCents;
    if (!Number.isSafeInteger(totalCents))
      throw invalid('Revisá las cantidades.', 'invalid_items');
    lines.push({
      serviceId: service.id,
      name: service.name,
      quantity: item.quantity,
      unitPriceCents,
      totalCents,
      variantId: item.variantId,
      photoServiceId: service.photo_service_id,
    });
  }
  const order = new Map(catalog.map((service, index) => [service.id, index]));
  lines.sort((a, b) => order.get(a.serviceId)! - order.get(b.serviceId)!);
  const totalCents = lines.reduce((sum, line) => sum + line.totalCents, 0);
  if (!Number.isSafeInteger(totalCents))
    throw invalid('Revisá las cantidades.', 'invalid_items');
  return { lines, totalCents };
}

/** Business rules raised by the SQL functions (`cc_error:<code>`) as safe API errors. */
export function orderRuleToApiError(code: string) {
  switch (code) {
    case 'price_changed':
      return new ApiError(
        'Los precios cambiaron. Revisá el total actualizado.',
        409,
        'price_changed',
      );
    case 'service_unavailable':
      return new ApiError(
        'Uno de los tamaños ya no está disponible. Actualizá la página.',
        409,
        'service_unavailable',
      );
    case 'invalid_phone':
      return new ApiError(
        'Revisá el número de WhatsApp.',
        422,
        'invalid_phone',
      );
    case 'uploads_pending':
      return new ApiError(
        'Esperá a que terminen todas las cargas antes de confirmar.',
        409,
        'uploads_pending',
      );
    case 'no_files':
      return new ApiError(
        'Todavía no hay fotos completas para confirmar el pedido.',
        409,
        'no_uploaded_files',
      );
    case 'order_not_found':
      return new ApiError('Link inválido.', 404, 'link_invalid');
    case 'too_many_links':
      return new ApiError(
        'Demasiados intentos. Probá más tarde.',
        429,
        'rate_limited',
      );
    case 'account_inactive':
      return new ApiError(
        'Tu cuenta profesional no está activa. Escribinos para revisarla.',
        403,
        'account_inactive',
      );
    case 'no_professional_list':
      return new ApiError(
        'Tu cuenta todavía no tiene una lista de precios asignada. Escribinos para configurarla.',
        403,
        'no_professional_list',
      );
    case 'invalid_quantity':
      return invalid('Revisá las cantidades.', 'invalid_items');
    case 'no_branch':
    case 'no_owner':
      return new ApiError(
        'Los pedidos online no están disponibles por el momento.',
        503,
        'orders_unavailable',
      );
    default:
      return invalid('La solicitud no es válida.');
  }
}

export type ParsedSubmit = {
  expectedFiles: Record<string, number> | null;
  acceptPartial: boolean;
  uploadIds: string[] | null;
};

export function parseSubmitPayload(
  input: Partial<PublicOrderSubmitPayload>,
  limits: OrderLimits = PUBLIC_ORDER_LIMITS,
): ParsedSubmit {
  const acceptPartial = input.acceptPartial;
  if (acceptPartial !== undefined && typeof acceptPartial !== 'boolean')
    throw invalid('La solicitud no es válida.');
  let uploadIds: string[] | null = null;
  if (input.uploadIds !== undefined && input.uploadIds !== null) {
    if (
      !Array.isArray(input.uploadIds) ||
      input.uploadIds.length > limits.maxUploads ||
      input.uploadIds.some((id) => typeof id !== 'string' || !UUID.test(id))
    )
      throw invalid('La solicitud no es válida.');
    uploadIds = [...new Set(input.uploadIds.map((id) => id.toLowerCase()))];
  }
  const expected = input.expectedFiles;
  if (expected === undefined || expected === null)
    return {
      expectedFiles: null,
      acceptPartial: acceptPartial === true,
      uploadIds,
    };
  if (
    typeof expected !== 'object' ||
    Array.isArray(expected) ||
    Object.keys(expected).length > limits.maxServices * 2
  )
    throw invalid('La solicitud no es válida.');
  const clean: Record<string, number> = {};
  for (const [key, count] of Object.entries(expected)) {
    if (
      !Number.isInteger(count) ||
      count < 0 ||
      count > limits.maxFilesPerDestination
    )
      throw invalid('La solicitud no es válida.');
    clean[key] = count;
  }
  return {
    expectedFiles: clean,
    acceptPartial: acceptPartial === true,
    uploadIds,
  };
}

/* ───────────────────────────── final file names ───────────────────────────── */

export const copiesLabel = (copies: number) =>
  `${copies}${copies === 1 ? 'copia' : 'copias'}`;

/** `.jpg`, `.HEIC`… exactly as the customer's file had it; nothing when there is none. */
export function fileExtension(name: string) {
  return /\.[A-Za-z0-9]{1,8}$/.exec(name)?.[0] ?? '';
}

type NameableFile = {
  id: string;
  original_filename: string;
  copies: number;
  created_at: string;
};

/**
 * The name each photo of ONE folder gets in Drive: `001_3copias.jpg`. The number is the photo's
 * position in the order the customer sees (the position of its upload id in `ranking`), with
 * creation time and id as deterministic tie-breakers, so parallel uploads never change it. The
 * copies are the ones stored for the file, which are the ones the order is priced with. Names
 * are unique within the folder because the number is.
 */
export function planFinalNames(
  files: NameableFile[],
  ranking: string[] | null = null,
): Map<string, string> {
  const rank = new Map((ranking ?? []).map((id, index) => [id, index]));
  const ordered = [...files].sort(
    (a, b) =>
      (rank.get(a.id) ?? Number.MAX_SAFE_INTEGER) -
        (rank.get(b.id) ?? Number.MAX_SAFE_INTEGER) ||
      a.created_at.localeCompare(b.created_at) ||
      a.id.localeCompare(b.id),
  );
  const width = Math.max(3, String(ordered.length).length);
  return new Map(
    ordered.map((file, index) => [
      file.id,
      `${String(index + 1).padStart(width, '0')}_${copiesLabel(file.copies)}${fileExtension(file.original_filename)}`,
    ]),
  );
}

export type OrderGap = { name: string; uploaded: number; expected: number };

/**
 * Sizes whose photos did not all arrive. Without the browser's counts (an older page) a size
 * with no photo at all is the only gap that can be proven; with them, any shortfall is.
 */
export function findOrderGaps(
  items: { id: string; name: string }[],
  uploadedByItem: Map<string, number>,
  expectedByItem: Map<string, number> | null,
): OrderGap[] {
  const gaps: OrderGap[] = [];
  for (const item of items) {
    const uploaded = uploadedByItem.get(item.id) ?? 0;
    const expected = expectedByItem ? (expectedByItem.get(item.id) ?? 0) : 1;
    if (uploaded < expected) gaps.push({ name: item.name, uploaded, expected });
  }
  return gaps;
}

export function incompleteOrderError(gaps: OrderGap[]) {
  const detail = gaps
    .map((gap) =>
      gap.expected > 1
        ? `${gap.name} (llegaron ${gap.uploaded} de ${gap.expected})`
        : gap.name,
    )
    .join(', ');
  return new ApiError(
    `Faltan fotos de: ${detail}. Reintentá enviarlas antes de confirmar.`,
    409,
    'order_incomplete',
  );
}
